<!--
  The Avarok brand artwork, as vector definitions.

  The mark is three chevrons at stroke 76, arm 320x280, gap 280, box 956x636.
  The wordmark keeps the Avarok signature A (arrow shaft) from the brand
  outlines, then "varok" in the same lockup. The guidelines forbid recolouring,
  outlining and glow. The only substitution here is swapping the literal brand
  greys and chevron hues for the tokens that hold those same values, so the
  lockup follows the palette instead of pinning a second copy of it.

  Rendered once per document by <AvarokLockup kind="defs" />, then referenced by
  <use href="#avarok-mark"> from every lockup on the page.

  Sizing is by WIDTH, because the guideline minimums are widths:
  logo-horizontal >= 120px, logo-full >= 220px. Clear space (one chevron gap,
  x = 140 lockup units) is CSS margin rather than viewBox padding, which would
  silently shrink the artwork below the minimum.
-->
<script>
  /** 'defs' emits the definitions; 'horizontal' is the nav lockup (mark +
   *  wordmark); 'full' adds the tagline and is for footers and about pages;
   *  'mark' is the bare three chevrons. */
  let { kind = 'horizontal', width = null, label = 'Avarok', class: klass = '' } = $props();
</script>

{#if kind === 'defs'}
<svg class="avarok-defs" width="0" height="0" aria-hidden="true" focusable="false">
  <defs>
    <linearGradient id="gold-cut" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0.5" stop-color="var(--ch-green)"/><stop offset="0.5" stop-color="var(--ch-gold)"/>
    </linearGradient>
    <!-- Mark: three chevrons. Stroke 76, arm 320×280, gap 280, box 956×636. -->
    <g id="avarok-mark" fill="none" stroke-width="76" stroke-linecap="round" stroke-linejoin="round">
      <path d="M38 38L358 318L38 598" stroke="var(--ch-violet)"/>
      <path d="M318 38L638 318L318 598" stroke="var(--ch-cyan)"/>
      <path d="M598 38L918 318L598 598" stroke="url(#gold-cut)"/>
    </g>
