<style>
  .avarok-defs { position: absolute; }
  .logo { display: block; height: auto; }
  /* Clear space is one chevron gap: x = 140 lockup units, which is
     140/1365 = 10.26% of the horizontal and full lockups' rendered width. */
  .logo-h { width: 153px; margin: calc(153px * 0.1026); }   /* >= 120px */
  .logo-f { width: 244px; margin: calc(244px * 0.1026); }   /* >= 220px */
  .logo-m { width: 30px; }
  @media (max-width: 520px) {
    .logo-h { width: 135px; margin: calc(135px * 0.1026); }
  }
</style>
